create table if not exists public.account_deletion_requests(user_id uuid primary key references auth.users(id) on delete cascade,status text not null default 'pending' check(status in('pending','processing','completed')),requested_at timestamptz not null default now(),completed_at timestamptz);
alter table public.account_deletion_requests enable row level security;grant select,insert,update on public.account_deletion_requests to authenticated;create policy "owners request deletion" on public.account_deletion_requests for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
